import { Object3D } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {import('three/webgpu').Object3D} THREEObject3D
 * @typedef {Object} NodeConfig
 * @property {[number, number, number]} position
 * @property {[number, number, number]} rotation
 * @property {[number, number, number]} scale
 * @property {string} meshUrl
 *
 * @typedef {Object} NodeContext
 * @property {(url:string)=>any} glbLoader            // synchronously returns a GLTF-like object
 */

/**
 * Creates the thumbnail card node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREEObject3D}
 */
export default function createNode(config, ctx) {
    // root container
    const root = new Object3D();

    // apply transform
    if (config.position) root.position.set(...config.position);
    if (config.rotation) root.rotation.set(...config.rotation);
    if (config.scale) root.scale.set(...config.scale);

    // load GLB (synchronous via ctx.glbLoader)
    const gltf = ctx.glbLoader(config.meshUrl);
    let meshRoot = null;

    if (gltf && gltf.scene) {
        meshRoot = gltf.scene.clone();
    } else if (gltf && gltf.isObject3D) {
        meshRoot = gltf.clone();
    } else {
        console.warn('GLB loader did not return a usable object for', config.meshUrl);
        meshRoot = new Object3D(); // fallback placeholder
    }

    root.add(meshRoot);

    // ----- Hover lift animation (rise‑in) -----
    const liftAmount = 0.15; // scene units
    const hoverTimeline = gsap.timeline({ paused: true, defaults: { ease: 'power3.out' } });
    hoverTimeline.to(root.position, {
        y: root.position.y + liftAmount,
        duration: 0.3,
    });

    // ----- Event handlers -----
    root.userData.handlers = {
        pointerover: () => {
            hoverTimeline.play();
        },
        pointerout: () => {
            hoverTimeline.reverse();
        },
        click: () => {
            // Emit semantic event for navigation
            root.dispatchEvent({ type: 'hub-home.select' });
        },
    };

    // ----- Cleanup -----
    root.userData.cleanup = () => {
        hoverTimeline.kill();

        // Dispose geometries and materials from the loaded GLB
        meshRoot.traverse((obj) => {
            if (obj.isMesh) {
                if (obj.geometry) obj.geometry.dispose();
                if (Array.isArray(obj.material)) {
                    obj.material.forEach((m) => m && m.dispose && m.dispose());
                } else if (obj.material && obj.material.dispose) {
                    obj.material.dispose();
                }
            }
        });
    };

    return root;
}
